def solve(n):
    """Return the count of primes less than n using Sieve of Eratosthenes."""
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

def solve(s: str) -> int:
    """Return the length of the longest substring of `s` without repeating characters.
    Uses a sliding window with a dictionary storing the latest index of each character.
    """
    last_index = {}
    left = 0
    max_len = 0
    for right, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= left:
            # character repeated within current window, move left bound
            left = last_index[ch] + 1
        last_index[ch] = right
        cur_len = right - left + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

