def solve(matrix):
    from fractions import Fraction
    if not matrix:
        return 1
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    A = [[Fraction(val) for val in row] for row in matrix]
    sign = 1
    for i in range(n):
        # find pivot
        pivot_row = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0
        if pivot_row != i:
            A[i], A[pivot_row] = A[pivot_row], A[i]
            sign = -sign
        pivot = A[i][i]
        for r in range(i+1, n):
            factor = A[r][i] / pivot
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    det = sign
    for i in range(n):
        det *= A[i][i]
    return int(det)

