    """Return the maximum total value achievable with 0/1 knapsack.
    Handles edge cases such as negative/zero capacity, mismatched input lengths,
    and items with non‑positive weight.
    """
    # Guard against non‑positive capacity
    if capacity <= 0:
        return 0
    # Ensure lists are the same length; ignore extra entries
    n = min(len(weights), len(values))
    if n == 0:
        return 0
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # Skip items that cannot be taken (negative weight or too heavy)
        if w <= 0:
            # Zero or negative weight: can be taken at most once, add its value to all states
            if w < 0:
                # Negative weight would increase capacity unlimitedly; treat as unusable
                continue
            # w == 0
            for c in range(capacity, -1, -1):
                dp[c] = dp[c] + v
            continue
        if w > capacity:
            continue
        # Standard 0/1 knapsack DP, iterate backwards
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    # The best value may be at any capacity up to the limit
    return max(dp)
