    """0/1 knapsack: maximum total value with given weights and values.
    Handles mismatched lengths by considering pairs up to the shorter list.
    Returns the maximum value for any total weight <= capacity.
    """
    if capacity <= 0:
        return 0
    # Pair weights and values safely
    items = [(w, v) for w, v in zip(weights, values) if w >= 0 and v >= 0]
    if not items:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in items:
        if w > capacity:
            continue
        # iterate backwards to avoid reuse
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return max(dp)

