def solve(weights, values, capacity):
    """0/1 knapsack returning the maximum total value not exceeding *capacity*.
    Handles zero‑weight items by adding their values up front (they never consume capacity).
    """
    if capacity <= 0:
        # Only zero‑weight items can contribute
        return sum(v for w, v in zip(weights, values) if w == 0 and v > 0)
    # Separate zero‑weight items
    zero_value = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_value += v
        elif w > 0:
            items.append((w, v))
        # ignore negative weights/values as they are invalid for knapsack
    dp = [0] * (capacity + 1)
    for w, v in items:
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return zero_value + max(dp)

