def solve(tokens):
    """Evaluate an expression given in Reverse Polish Notation.
    Tokens are strings representing integers or the operators '+', '-', '*', '/'.
    Division truncates toward zero as required.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # token == '/'
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

