def solve(weights, values, capacity):
    """Return the maximum total value for 0/1 knapsack given weights, values, capacity.
    Uses O(capacity) DP.
    """
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        for c in range(capacity, w - 1, -1):
            if dp[c - w] + v > dp[c]:
                dp[c] = dp[c - w] + v
    return dp[capacity]

