def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    The algorithm splits the path by '/', uses a stack to process components:
    - '' or '.' are ignored
    - '..' pops the stack if possible
    - otherwise the component is a directory name and is pushed.
    The result is '/' + '/'.join(stack). If the stack is empty, return '/'.
    """
    if not isinstance(path, str):
        return ''
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty and we are at root, stay at root
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

